namespace {

// Fill year-0 unfished numbers at age, which the equilibrium initial numbers
// at age are scaled from.
void CalculateUnfishedYear0(
    std::shared_ptr<fims_popdy::CatchAtAge<double>>& catch_at_age_model,
    std::shared_ptr<fims_popdy::Population<double>>& population) {
  auto& dq =
      catch_at_age_model->GetPopulationDerivedQuantities(population->GetId());
  for (size_t age = 0; age < population->n_ages; age++) {
    if (age == 0) {
      dq["unfished_numbers_at_age"][age] =
          fims_math::exp(population->recruitment->log_rzero[0]);
    } else {
      catch_at_age_model->CalculateUnfishedInitialNumbersAA(population, age,
                                                            age);
    }
  }
}

// CatchAtAge_CalculateEquilibriumInitialNumbersAA
// IO correctness
TEST_F(CAAEvaluateTestFixture,
       HandlesCorrectInput_CatchAtAge_CalculateEquilibriumInitialNumbersAA) {
  auto& dq =
      catch_at_age_model->GetPopulationDerivedQuantities(population->GetId());
  // 3 cohorts recruited before the first year, so element 3 of the
  // deviations is the first-year recruitment and elements 2, 1, and 0 are the
  // cohorts that are 1, 2, and 3 years older.
  size_t n_initial_devs = 3;
  double offset = 0.2;
  population->initial_numbers = "equilibrium";
  population->n_initial_devs = n_initial_devs;
  population->log_init_rzero_offset.resize(1);
  population->log_init_rzero_offset[0] = offset;
  population->recruitment->log_recruit_devs.resize(n_years + n_initial_devs);
  for (size_t i = 0; i < population->recruitment->log_recruit_devs.size();
       i++) {
    population->recruitment->log_recruit_devs[i] = 0.1 * (i + 1);
  }

  CalculateUnfishedYear0(catch_at_age_model, population);
  for (int age = 0; age < population->n_ages; age++) {
    catch_at_age_model->CalculateEquilibriumInitialNumbersAA(population, age,
                                                             age);
  }

  // Each cohort with a deviation is scaled by exp(offset + deviation). Older
  // ages, including the plus group, are scaled by exp(offset) only.
  for (int age = 0; age < population->n_ages; age++) {
    double log_scale = offset;
    if (age <= static_cast<int>(n_initial_devs)) {
      log_scale += 0.1 * (n_initial_devs - age + 1);
    }
    double expected = dq["unfished_numbers_at_age"][age] * std::exp(log_scale);
    EXPECT_NEAR(dq["numbers_at_age"][age], expected, 1e-10 * expected);
  }
}

// CatchAtAge_CalculateEquilibriumInitialNumbersAA
// Edge handling
TEST_F(CAAEvaluateTestFixture,
       HandlesZeroOffsetAndDeviations_CatchAtAge_EquilibriumEqualsUnfished) {
  auto& dq =
      catch_at_age_model->GetPopulationDerivedQuantities(population->GetId());
  // With no offset and no deviations, the first-year age structure is the
  // unfished equilibrium, including the plus group.
  size_t n_initial_devs = n_ages - 2;
  population->initial_numbers = "equilibrium";
  population->n_initial_devs = n_initial_devs;
  population->log_init_rzero_offset.resize(1);
  population->log_init_rzero_offset[0] = 0.0;
  population->recruitment->log_recruit_devs.resize(n_years + n_initial_devs);
  for (size_t i = 0; i < population->recruitment->log_recruit_devs.size();
       i++) {
    population->recruitment->log_recruit_devs[i] = 0.0;
  }

  CalculateUnfishedYear0(catch_at_age_model, population);
  for (int age = 0; age < population->n_ages; age++) {
    catch_at_age_model->CalculateEquilibriumInitialNumbersAA(population, age,
                                                             age);
    EXPECT_EQ(dq["numbers_at_age"][age], dq["unfished_numbers_at_age"][age]);
  }
}

// CatchAtAge_CalculateRecruitment
// IO correctness
TEST_F(CAAEvaluateTestFixture,
       HandlesEquilibriumDeviations_CatchAtAge_CalculateRecruitment) {
  auto& dq =
      catch_at_age_model->GetPopulationDerivedQuantities(population->GetId());
  // Under an equilibrium start, recruitment in year y uses deviation
  // y + n_initial_devs because the first n_initial_devs + 1 deviations belong
  // to the first-year age structure.
  size_t n_initial_devs = 3;
  population->initial_numbers = "equilibrium";
  population->n_initial_devs = n_initial_devs;
  population->recruitment->log_recruit_devs.resize(n_years + n_initial_devs);
  for (size_t i = 0; i < population->recruitment->log_recruit_devs.size();
       i++) {
    population->recruitment->log_recruit_devs[i] = 0.1 * (i + 1);
  }
  population->recruitment->log_expected_recruitment.resize(n_years +
                                                           n_initial_devs);

  // Spawning biomass in the year before recruitment sets the mean
  int year = 5;
  for (size_t y = 0; y < n_years; y++) {
    for (size_t age = 0; age < n_ages; age++) {
      catch_at_age_model->CalculateMaturityAA(
          population, y * population->n_ages + age, y, age);
    }
  }
  catch_at_age_model->CalculateSpawningBiomass(
      population, (year - 1) * population->n_ages, year - 1, 0);

  int i_age_year = year * population->n_ages;
  catch_at_age_model->CalculateRecruitment(population, i_age_year, year, year);

  double phi_0 = catch_at_age_model->CalculateSBPR0(population);
  double expected_mean = population->recruitment->evaluate_mean(
      dq["spawning_biomass"][year - 1], phi_0);
  double expected = expected_mean * std::exp(0.1 * (year + n_initial_devs + 1));
  EXPECT_NEAR(dq["numbers_at_age"][i_age_year], expected, 1e-10 * expected);
}

// CatchAtAge_Initialize
// Error handling
TEST_F(CAAEvaluateTestFixture,
       CaptureError_CatchAtAge_InitializeEquilibriumDeviations) {
  population->initial_numbers = "equilibrium";
  // The fixture's n_years - 1 deviations are the free layout, which has no
  // deviation for the first year.
  EXPECT_THROW(catch_at_age_model->Initialize(), std::runtime_error);

  // A deviation for the plus group cohort is one too many.
  population->recruitment->log_recruit_devs.resize(n_years + n_ages - 1);
  EXPECT_THROW(catch_at_age_model->Initialize(), std::runtime_error);

  // The oldest cohort below the plus group sets n_initial_devs to n_ages - 2.
  population->recruitment->log_recruit_devs.resize(n_years + n_ages - 2);
  EXPECT_NO_THROW(catch_at_age_model->Initialize());
  EXPECT_EQ(population->n_initial_devs, static_cast<size_t>(n_ages - 2));
  EXPECT_EQ(population->recruitment->log_expected_recruitment.size(),
            static_cast<size_t>(n_years + n_ages - 2));
}
}  // namespace
